1	package filter
2	
3	import (
4		"fmt"
5		"strings"
6	
7		"github.com/pkg/errors"
8	)
9	
10	type renderer struct {
11		schema             Schema
12		dialect            DialectName
13		placeholderOffset  int
14		placeholderCounter int
15		args               []any
16	}
17	
18	type renderResult struct {
19		sql           string
20		trivial       bool
21		unsatisfiable bool
22	}
23	
24	func newRenderer(schema Schema, opts RenderOptions) *renderer {
25		return &renderer{
26			schema:            schema,
27			dialect:           opts.Dialect,
28			placeholderOffset: opts.PlaceholderOffset,
29		}
30	}
31	
32	func (r *renderer) Render(cond Condition) (Statement, error) {
33		result, err := r.renderCondition(cond)
34		if err != nil {
35			return Statement{}, err
36		}
37		args := r.args
38		if args == nil {
39			args = []any{}
40		}
41	
42		switch {
43		case result.unsatisfiable:
44			return Statement{
45				SQL:  "1 = 0",
46				Args: args,
47			}, nil
48		case result.trivial:
49			return Statement{
50				SQL:  "",
51				Args: args,
52			}, nil
53		default:
54			return Statement{
55				SQL:  result.sql,
56				Args: args,
57			}, nil
58		}
59	}
60	
61	func (r *renderer) renderCondition(cond Condition) (renderResult, error) {
62		switch c := cond.(type) {
63		case *LogicalCondition:
64			return r.renderLogicalCondition(c)
65		case *NotCondition:
66			return r.renderNotCondition(c)
67		case *FieldPredicateCondition:
68			return r.renderFieldPredicate(c)
69		case *ComparisonCondition:
70			return r.renderComparison(c)
71		case *InCondition:
72			return r.renderInCondition(c)
73		case *ElementInCondition:
74			return r.renderElementInCondition(c)
75		case *TextMatchCondition:
76			return r.renderTextMatch(c)
77		case *RegexCondition:
78			return r.renderRegex(c)
79		case *ListComprehensionCondition:
80			return r.renderListComprehension(c)
81		case *ConstantCondition:
82			if c.Value {
83				return renderResult{trivial: true}, nil
84			}
85			return renderResult{sql: "1 = 0", unsatisfiable: true}, nil
86		default:
87			return renderResult{}, errors.Errorf("unsupported condition type %T", c)
88		}
89	}
90	
91	func (r *renderer) renderLogicalCondition(cond *LogicalCondition) (renderResult, error) {
92		left, err := r.renderCondition(cond.Left)
93		if err != nil {
94			return renderResult{}, err
95		}
96		right, err := r.renderCondition(cond.Right)
97		if err != nil {
98			return renderResult{}, err
99		}
100	
101		switch cond.Operator {
102		case LogicalAnd:
103			return combineAnd(left, right), nil
104		case LogicalOr:
105			return combineOr(left, right), nil
106		default:
107			return renderResult{}, errors.Errorf("unsupported logical operator %s", cond.Operator)
108		}
109	}
110	
111	func (r *renderer) renderNotCondition(cond *NotCondition) (renderResult, error) {
112		child, err := r.renderCondition(cond.Expr)
113		if err != nil {
114			return renderResult{}, err
115		}
116	
117		if child.trivial {
118			return renderResult{sql: "1 = 0", unsatisfiable: true}, nil
119		}
120		if child.unsatisfiable {
121			return renderResult{trivial: true}, nil
122		}
123		return renderResult{
124			sql: fmt.Sprintf("NOT (%s)", child.sql),
125		}, nil
126	}
127	
128	func (r *renderer) renderFieldPredicate(cond *FieldPredicateCondition) (renderResult, error) {
129		field, ok := r.schema.Field(cond.Field)
130		if !ok {
131			return renderResult{}, errors.Errorf("unknown field %q", cond.Field)
132		}
133	
134		switch field.Kind {
135		case FieldKindBoolColumn:
136			column := qualifyColumn(r.dialect, field.Column)
137			return renderResult{
138				sql: fmt.Sprintf("%s IS TRUE", column),
139			}, nil
140		case FieldKindJSONBool:
141			sql, err := r.jsonBoolPredicate(field)
142			if err != nil {
143				return renderResult{}, err
144			}
145			return renderResult{sql: sql}, nil
146		default:
147			return renderResult{}, errors.Errorf("field %q cannot be used as a predicate", cond.Field)
148		}
149	}
150	
151	func (r *renderer) renderComparison(cond *ComparisonCondition) (renderResult, error) {
152		switch left := cond.Left.(type) {
153		case *FieldRef:
154			field, ok := r.schema.Field(left.Name)
155			if !ok {
156				return renderResult{}, errors.Errorf("unknown field %q", left.Name)
157			}
158			switch field.Kind {
159			case FieldKindBoolColumn:
160				return r.renderBoolColumnComparison(field, cond.Operator, cond.Right)
161			case FieldKindJSONBool:
162				return r.renderJSONBoolComparison(field, cond.Operator, cond.Right)
163			case FieldKindScalar:
164				return r.renderScalarComparison(field, cond.Operator, cond.Right)
165			default:
166				return renderResult{}, errors.Errorf("field %q does not support comparison", field.Name)
167			}
168		case *FunctionValue:
169			return r.renderFunctionComparison(left, cond.Operator, cond.Right)
170		case *FieldAccessorValue:
171			return r.renderAccessorComparison(left, cond.Operator, cond.Right)
172		default:
173			return renderResult{}, errors.New("comparison must start with a field reference or supported function")
174		}
175	}
176	
177	// accessorSpec maps a CEL timestamp accessor to per-dialect SQL date-part tokens
178	// and the offset to subtract so the result matches CEL's base (e.g. CEL months
179	// are 0-based but every dialect reports 1-based, so off=1). off is indexed
180	// [sqlite, postgres, mysql].
181	type accessorSpec struct {
182		sqlite string // strftime format specifier
183		pg     string // EXTRACT field
184		mysql  string // function name
185		off    [3]int
186	}
187	
188	var accessorSpecs = map[string]accessorSpec{
189		"getFullYear":   {"%Y", "YEAR", "YEAR", [3]int{0, 0, 0}},
190		"getMonth":      {"%m", "MONTH", "MONTH", [3]int{1, 1, 1}},
191		"getDate":       {"%d", "DAY", "DAYOFMONTH", [3]int{0, 0, 0}},
192		"getDayOfMonth": {"%d", "DAY", "DAYOFMONTH", [3]int{1, 1, 1}},
193		"getDayOfWeek":  {"%w", "DOW", "DAYOFWEEK", [3]int{0, 0, 1}},
194		"getDayOfYear":  {"%j", "DOY", "DAYOFYEAR", [3]int{1, 1, 1}},
195		"getHours":      {"%H", "HOUR", "HOUR", [3]int{0, 0, 0}},
196		"getMinutes":    {"%M", "MINUTE", "MINUTE", [3]int{0, 0, 0}},
197		"getSeconds":    {"%S", "SECOND", "SECOND", [3]int{0, 0, 0}},
198	}
199	
200	func (r *renderer) renderAccessorComparison(acc *FieldAccessorValue, op ComparisonOperator, right ValueExpr) (renderResult, error) {
201		field, ok := r.schema.Field(acc.Field)
202		if !ok {
203			return renderResult{}, errors.Errorf("unknown field %q", acc.Field)
204		}
205		value, err := expectNumericLiteral(right)
206		if err != nil {
207			return renderResult{}, err
208		}
209		expr, err := r.timestampAccessorExpr(field, acc.Accessor)
210		if err != nil {
211			return renderResult{}, err
212		}
213		placeholder := r.addArg(value)
214		return renderResult{
215			sql: fmt.Sprintf("%s %s %s", expr, sqlOperator(op), placeholder),
216		}, nil
217	}
218	
219	// timestampAccessorExpr builds a dialect-specific integer expression for a CEL
220	// timestamp accessor. Extraction is UTC on SQLite/Postgres (epoch columns); on
221	// MySQL the TIMESTAMP column is read in the server session time zone.
222	func (r *renderer) timestampAccessorExpr(field Field, accessor string) (string, error) {
223		spec, ok := accessorSpecs[accessor]
224		if !ok {
225			return "", errors.Errorf("unsupported timestamp accessor %q", accessor)
226		}
227		col := qualifyColumn(r.dialect, field.Column)
228		var base string
229		var off int
230		switch r.dialect {
231		case DialectSQLite:
232			base = fmt.Sprintf("CAST(strftime('%s', %s, 'unixepoch') AS INTEGER)", spec.sqlite, col)
233			off = spec.off[0]
234		case DialectPostgres:
235			base = fmt.Sprintf("CAST(EXTRACT(%s FROM to_timestamp(%s) AT TIME ZONE 'UTC') AS INTEGER)", spec.pg, col)
236			off = spec.off[1]
237		case DialectMySQL:
238			base = fmt.Sprintf("%s(%s)", spec.mysql, col)
239			off = spec.off[2]
240		default:
241			return "", errors.Errorf("unsupported dialect %q", r.dialect)
242		}
243		if off != 0 {
244			base = fmt.Sprintf("(%s - %d)", base, off)
245		}
246		return base, nil
247	}
248	
249	func (r *renderer) renderFunctionComparison(fn *FunctionValue, op ComparisonOperator, right ValueExpr) (renderResult, error) {
250		if fn.Name != "size" {
251			return renderResult{}, errors.Errorf("unsupported function %s in comparison", fn.Name)
252		}
253		if len(fn.Args) != 1 {
254			return renderResult{}, errors.New("size() expects one argument")
255		}
256		fieldArg, ok := fn.Args[0].(*FieldRef)
257		if !ok {
258			return renderResult{}, errors.New("size() argument must be a field")
259		}
260	
261		field, ok := r.schema.Field(fieldArg.Name)
262		if !ok {
263			return renderResult{}, errors.Errorf("unknown field %q", fieldArg.Name)
264		}
265		if field.Kind == FieldKindVirtualAlias {
266			field, ok = r.schema.ResolveAlias(fieldArg.Name)
267			if !ok {
268				return renderResult{}, errors.Errorf("invalid alias %q", fieldArg.Name)
269			}
270		}
271	
272		value, err := expectNumericLiteral(right)
273		if err != nil {
274			return renderResult{}, err
275		}
276	
277		var expr string
278		switch {
279		case field.Kind == FieldKindJSONList:
280			expr = jsonArrayLengthExpr(r.dialect, field)
281		case field.Kind == FieldKindScalar && field.Type == FieldTypeString:
282			expr = stringLengthExpr(r.dialect, field.columnExpr(r.dialect))
283		default:
284			return renderResult{}, errors.Errorf("size() does not support field %q", field.Name)
285		}
286	
287		placeholder := r.addArg(value)
288		return renderResult{
289			sql: fmt.Sprintf("%s %s %s", expr, sqlOperator(op), placeholder),
290		}, nil
291	}
292	
293	// stringLengthExpr returns the character-count expression for a string column.
294	// MySQL's LENGTH counts bytes, so CHAR_LENGTH is used to count characters and
295	// match CEL's size() code-point semantics; SQLite/Postgres LENGTH already counts
296	// characters.
297	func stringLengthExpr(d DialectName, colExpr string) string {
298		if d == DialectMySQL {
299			return fmt.Sprintf("CHAR_LENGTH(%s)", colExpr)
300		}
301		return fmt.Sprintf("LENGTH(%s)", colExpr)
302	}
303	
304	func (r *renderer) renderScalarComparison(field Field, op ComparisonOperator, right ValueExpr) (renderResult, error) {
305		lit, err := expectLiteral(right)
306		if err != nil {
307			return renderResult{}, err
308		}
309	
310		columnExpr := field.columnExpr(r.dialect)
311		if lit == nil {
312			switch op {
313			case CompareEq:
314				return renderResult{sql: fmt.Sprintf("%s IS NULL", columnExpr)}, nil
315			case CompareNeq:
316				return renderResult{sql: fmt.Sprintf("%s IS NOT NULL", columnExpr)}, nil
317			default:
318				return renderResult{}, errors.Errorf("operator %s not supported for null comparison", op)
319			}
320		}
321	
322		placeholder := ""
323		switch field.Type {
324		case FieldTypeString:
325			value, ok := lit.(string)
326			if !ok {
327				return renderResult{}, errors.Errorf("field %q expects string value", field.Name)
328			}
329			placeholder = r.addArg(value)
330		case FieldTypeInt, FieldTypeTimestamp:
331			num, err := toInt64(lit)
332			if err != nil {
333				return renderResult{}, errors.Wrapf(err, "field %q expects integer value", field.Name)
334			}
335			placeholder = r.addArg(num)
336		default:
337			return renderResult{}, errors.Errorf("unsupported data type %q for field %s", field.Type, field.Name)
338		}
339	
340		return renderResult{
341			sql: fmt.Sprintf("%s %s %s", columnExpr, sqlOperator(op), placeholder),
342		}, nil
343	}
344	
345	func (r *renderer) renderBoolColumnComparison(field Field, op ComparisonOperator, right ValueExpr) (renderResult, error) {
346		value, err := expectBool(right)
347		if err != nil {
348			return renderResult{}, err
349		}
350		placeholder := r.addBoolArg(value)
351		column := qualifyColumn(r.dialect, field.Column)
352		return renderResult{
353			sql: fmt.Sprintf("%s %s %s", column, sqlOperator(op), placeholder),
354		}, nil
355	}
356	
357	func (r *renderer) renderJSONBoolComparison(field Field, op ComparisonOperator, right ValueExpr) (renderResult, error) {
358		value, err := expectBool(right)
359		if err != nil {
360			return renderResult{}, err
361		}
362	
363		jsonExpr := jsonExtractExpr(r.dialect, field)
364		switch r.dialect {
365		case DialectSQLite:
366			switch op {
367			case CompareEq:
368				if field.Name == "has_task_list" {
369					target := "0"
370					if value {
371						target = "1"
372					}
373					return renderResult{sql: fmt.Sprintf("%s = %s", jsonExpr, target)}, nil
374				}
375				if value {
376					return renderResult{sql: fmt.Sprintf("%s IS TRUE", jsonExpr)}, nil
377				}
378				return renderResult{sql: fmt.Sprintf("NOT(%s IS TRUE)", jsonExpr)}, nil
379			case CompareNeq:
380				if field.Name == "has_task_list" {
381					target := "0"
382					if value {
383						target = "1"
384					}
385					return renderResult{sql: fmt.Sprintf("%s != %s", jsonExpr, target)}, nil
386				}
387				if value {
388					return renderResult{sql: fmt.Sprintf("NOT(%s IS TRUE)", jsonExpr)}, nil
389				}
390				return renderResult{sql: fmt.Sprintf("%s IS TRUE", jsonExpr)}, nil
391			default:
392				return renderResult{}, errors.Errorf("operator %s not supported for boolean JSON field", op)
393			}
394		case DialectMySQL:
395			boolStr := "false"
396			if value {
397				boolStr = "true"
398			}
399			return renderResult{
400				sql: fmt.Sprintf("%s %s CAST('%s' AS JSON)", jsonExpr, sqlOperator(op), boolStr),
401			}, nil
402		case DialectPostgres:
403			placeholder := r.addArg(value)
404			return renderResult{
405				sql: fmt.Sprintf("(%s)::boolean %s %s", jsonExpr, sqlOperator(op), placeholder),
406			}, nil
407		default:
408			return renderResult{}, errors.Errorf("unsupported dialect %s", r.dialect)
409		}
410	}
411	
412	func (r *renderer) renderInCondition(cond *InCondition) (renderResult, error) {
413		fieldRef, ok := cond.Left.(*FieldRef)
414		if !ok {
415			return renderResult{}, errors.New("IN operator requires a field on the left-hand side")
416		}
417	
418		if fieldRef.Name == "tag" {
419			return r.renderTagInList(cond.Values)
420		}
421	
422		field, ok := r.schema.Field(fieldRef.Name)
423		if !ok {
424			return renderResult{}, errors.Errorf("unknown field %q", fieldRef.Name)
425		}
426	
427		if field.Kind != FieldKindScalar {
428			return renderResult{}, errors.Errorf("field %q does not support IN()", fieldRef.Name)
429		}
430	
431		return r.renderScalarInCondition(field, cond.Values)
432	}
433	
434	func (r *renderer) renderTagInList(values []ValueExpr) (renderResult, error) {
435		field, ok := r.schema.ResolveAlias("tag")
436		if !ok {
437			return renderResult{}, errors.New("tag attribute is not configured")
438		}
439	
440		conditions := make([]string, 0, len(values))
441		for _, v := range values {
442			lit, err := expectLiteral(v)
443			if err != nil {
444				return renderResult{}, err
445			}
446			str, ok := lit.(string)
447			if !ok {
448				return renderResult{}, errors.New("tags must be compared with string literals")
449			}
450	
451			switch r.dialect {
452			case DialectSQLite:
453				// Support hierarchical tags: match exact tag OR tags with this prefix (e.g., "book" matches "book" and "book/something")
454				exactMatch := fmt.Sprintf("%s LIKE %s", jsonArrayExpr(r.dialect, field), r.addArg(fmt.Sprintf(`%%"%s"%%`, str)))
455				prefixMatch := fmt.Sprintf("%s LIKE %s", jsonArrayExpr(r.dialect, field), r.addArg(fmt.Sprintf(`%%"%s/%%`, str)))
456				expr := fmt.Sprintf("(%s OR %s)", exactMatch, prefixMatch)
457				conditions = append(conditions, expr)
458			case DialectMySQL:
459				// Support hierarchical tags: match exact tag OR tags with this prefix
460				exactMatch := fmt.Sprintf("JSON_CONTAINS(%s, %s)", jsonArrayExpr(r.dialect, field), r.addArg(fmt.Sprintf(`"%s"`, str)))
461				prefixMatch := fmt.Sprintf("%s LIKE %s", jsonArrayExpr(r.dialect, field), r.addArg(fmt.Sprintf(`%%"%s/%%`, str)))
462				expr := fmt.Sprintf("(%s OR %s)", exactMatch, prefixMatch)
463				conditions = append(conditions, expr)
464			case DialectPostgres:
465				// Support hierarchical tags: match exact tag OR tags with this prefix
466				exactMatch := fmt.Sprintf("%s @> jsonb_build_array(%s::json)", jsonArrayExpr(r.dialect, field), r.addArg(fmt.Sprintf(`"%s"`, str)))
467				prefixMatch := fmt.Sprintf("(%s)::text LIKE %s", jsonArrayExpr(r.dialect, field), r.addArg(fmt.Sprintf(`%%"%s/%%`, str)))
468				expr := fmt.Sprintf("(%s OR %s)", exactMatch, prefixMatch)
469				conditions = append(conditions, expr)
470			default:
471				return renderResult{}, errors.Errorf("unsupported dialect %s", r.dialect)
472			}
473		}
474	
475		if len(conditions) == 1 {
476			return renderResult{sql: conditions[0]}, nil
477		}
478		return renderResult{
479			sql: fmt.Sprintf("(%s)", strings.Join(conditions, " OR ")),
480		}, nil
481	}
482	
483	func (r *renderer) renderElementInCondition(cond *ElementInCondition) (renderResult, error) {
484		field, ok := r.schema.Field(cond.Field)
485		if !ok {
486			return renderResult{}, errors.Errorf("unknown field %q", cond.Field)
487		}
488		if field.Kind != FieldKindJSONList {
489			return renderResult{}, errors.Errorf("field %q is not a tag list", cond.Field)
490		}
491	
492		lit, err := expectLiteral(cond.Element)
493		if err != nil {
494			return renderResult{}, err
495		}
496		str, ok := lit.(string)
497		if !ok {
498			return renderResult{}, errors.New("tags membership requires string literal")
499		}
500	
501		switch r.dialect {
502		case DialectSQLite:
503			sql := fmt.Sprintf("%s LIKE %s", jsonArrayExpr(r.dialect, field), r.addArg(fmt.Sprintf(`%%"%s"%%`, str)))
504			return renderResult{sql: sql}, nil
505		case DialectMySQL:
506			sql := fmt.Sprintf("JSON_CONTAINS(%s, %s)", jsonArrayExpr(r.dialect, field), r.addArg(fmt.Sprintf(`"%s"`, str)))
507			return renderResult{sql: sql}, nil
508		case DialectPostgres:
509			sql := fmt.Sprintf("%s @> jsonb_build_array(%s::json)", jsonArrayExpr(r.dialect, field), r.addArg(fmt.Sprintf(`"%s"`, str)))
510			return renderResult{sql: sql}, nil
511		default:
512			return renderResult{}, errors.Errorf("unsupported dialect %s", r.dialect)
513		}
514	}
515	
516	func (r *renderer) renderScalarInCondition(field Field, values []ValueExpr) (renderResult, error) {
517		placeholders := make([]string, 0, len(values))
518	
519		for _, v := range values {
520			lit, err := expectLiteral(v)
521			if err != nil {
522				return renderResult{}, err
523			}
524			switch field.Type {
525			case FieldTypeString:
526				str, ok := lit.(string)
527				if !ok {
528					return renderResult{}, errors.Errorf("field %q expects string values", field.Name)
529				}
530				placeholders = append(placeholders, r.addArg(str))
531			case FieldTypeInt:
532				num, err := toInt64(lit)
533				if err != nil {
534					return renderResult{}, err
535				}
536				placeholders = append(placeholders, r.addArg(num))
537			default:
538				return renderResult{}, errors.Errorf("field %q does not support IN() comparisons", field.Name)
539			}
540		}
541	
542		column := field.columnExpr(r.dialect)
543		return renderResult{
544			sql: fmt.Sprintf("%s IN (%s)", column, strings.Join(placeholders, ",")),
545		}, nil
546	}
547	
548	func (r *renderer) renderTextMatch(cond *TextMatchCondition) (renderResult, error) {
549		field, ok := r.schema.Field(cond.Field)
550		if !ok {
551			return renderResult{}, errors.Errorf("unknown field %q", cond.Field)
552		}
553		column := field.columnExpr(r.dialect)
554		pattern := likePattern(cond.Mode, cond.Value)
555		return renderResult{sql: r.foldedLike(column, pattern)}, nil
556	}
557	
558	func (r *renderer) renderRegex(cond *RegexCondition) (renderResult, error) {
559		field, ok := r.schema.Field(cond.Field)
560		if !ok {
561			return renderResult{}, errors.Errorf("unknown field %q", cond.Field)
562		}
563		column := field.columnExpr(r.dialect)
564		switch r.dialect {
565		case DialectPostgres:
566			// POSIX regex match operator.
567			return renderResult{sql: fmt.Sprintf("%s ~ %s", column, r.addArg(cond.Pattern))}, nil
568		case DialectMySQL, DialectSQLite:
569			// MySQL has a native REGEXP operator; SQLite uses the registered regexp() function.
570			return renderResult{sql: fmt.Sprintf("%s REGEXP %s", column, r.addArg(cond.Pattern))}, nil
571		default:
572			return renderResult{}, errors.Errorf("unsupported dialect %s", r.dialect)
573		}
574	}
575	
576	// foldedLike renders a case-insensitive LIKE comparison of colExpr against a
577	// (already metacharacter-escaped) pattern, using each dialect's case-folding.
578	func (r *renderer) foldedLike(colExpr, pattern string) string {
579		switch r.dialect {
580		case DialectSQLite:
581			// memos_unicode_lower gives Unicode-aware folding; ESCAPE '\' is required
582			// because SQLite has no default LIKE escape character.
583			return fmt.Sprintf(`memos_unicode_lower(%s) LIKE memos_unicode_lower(%s) ESCAPE '\'`, colExpr, r.addArg(pattern))
584		case DialectPostgres:
585			// ILIKE is case-insensitive; backslash is the default escape character.
586			return fmt.Sprintf("%s ILIKE %s", colExpr, r.addArg(pattern))
587		default: // MySQL: default collation is case-insensitive; backslash is the default escape.
588			return fmt.Sprintf("%s LIKE %s", colExpr, r.addArg(pattern))
589		}
590	}
591	
592	// likePattern escapes LIKE metacharacters in value and wraps it for the mode.
593	func likePattern(mode TextMatchMode, value string) string {
594		escaped := escapeLikeLiteral(value)
595		switch mode {
596		case TextMatchPrefix:
597			return escaped + "%"
598		case TextMatchSuffix:
599			return "%" + escaped
600		default:
601			return "%" + escaped + "%"
602		}
603	}
604	
605	// escapeLikeLiteral escapes the LIKE metacharacters \, %, and _ so user input
606	// is matched literally. Backslash is the escape character on all three dialects.
607	func escapeLikeLiteral(s string) string {
608		return strings.NewReplacer(`\`, `\\`, `%`, `\%`, `_`, `\_`).Replace(s)
609	}
610	
611	func (r *renderer) renderListComprehension(cond *ListComprehensionCondition) (renderResult, error) {
612		field, ok := r.schema.Field(cond.Field)
613		if !ok {
614			return renderResult{}, errors.Errorf("unknown field %q", cond.Field)
615		}
616	
617		if field.Kind != FieldKindJSONList {
618			return renderResult{}, errors.Errorf("field %q is not a JSON list", cond.Field)
619		}
620	
621		if cond.Kind == ComprehensionAll {
622			return r.renderTagAll(field, cond.Predicate)
623		}
624	
625		if cond.Kind == ComprehensionExistsOne {
626			return r.renderTagExistsOne(field, cond.Predicate)
627		}
628	
629		// Render based on predicate type
630		switch pred := cond.Predicate.(type) {
631		case *EqualsPredicate:
632			return r.renderTagEquals(field, pred.Value, cond.Kind)
633		case *StartsWithPredicate:
634			return r.renderTagStartsWith(field, pred.Prefix, cond.Kind)
635		case *EndsWithPredicate:
636			return r.renderTagEndsWith(field, pred.Suffix, cond.Kind)
637		case *ContainsPredicate:
638			return r.renderTagContains(field, pred.Substring, cond.Kind)
639		default:
640			return renderResult{}, errors.Errorf("unsupported predicate type %T in comprehension", pred)
641		}
642	}
643	
644	// renderTagAll renders tags.all(t, <pred>): the array is non-empty AND no element
645	// fails the predicate. Element predicates use plain CEL semantics (case-insensitive
646	// for startsWith/endsWith/contains, case-sensitive for ==), evaluated per element.
647	func (r *renderer) renderTagAll(field Field, pred PredicateExpr) (renderResult, error) {
648		arrayExpr := jsonArrayExpr(r.dialect, field)
649		elemCond, err := r.elementPredicateSQL(pred)
650		if err != nil {
651			return renderResult{}, err
652		}
653		switch r.dialect {
654		case DialectSQLite:
655			nonEmpty := fmt.Sprintf("%s IS NOT NULL AND %s != '[]'", arrayExpr, arrayExpr)
656			sub := fmt.Sprintf("NOT EXISTS (SELECT 1 FROM json_each(%s) WHERE NOT (%s))", arrayExpr, elemCond)
657			return renderResult{sql: fmt.Sprintf("(%s AND %s)", nonEmpty, sub)}, nil
658		case DialectMySQL:
659			nonEmpty := fmt.Sprintf("%s IS NOT NULL AND JSON_LENGTH(%s) > 0", arrayExpr, arrayExpr)
660			sub := fmt.Sprintf("NOT EXISTS (SELECT 1 FROM JSON_TABLE(%s, '$[*]' COLUMNS (value VARCHAR(512) PATH '$')) AS elem WHERE NOT (%s))", arrayExpr, elemCond)
661			return renderResult{sql: fmt.Sprintf("(%s AND %s)", nonEmpty, sub)}, nil
662		case DialectPostgres:
663			nonEmpty := fmt.Sprintf("%s IS NOT NULL AND jsonb_array_length(%s) > 0", arrayExpr, arrayExpr)
664			sub := fmt.Sprintf("NOT EXISTS (SELECT 1 FROM jsonb_array_elements_text(%s) AS elem(value) WHERE NOT (%s))", arrayExpr, elemCond)
665			return renderResult{sql: fmt.Sprintf("(%s AND %s)", nonEmpty, sub)}, nil
666		default:
667			return renderResult{}, errors.Errorf("unsupported dialect %s", r.dialect)
668		}
669	}
670	
671	// renderTagExistsOne renders tags.exists_one(t, <pred>): exactly one element
672	// satisfies the predicate, via a COUNT(...) = 1 subquery. A null or empty array
673	// yields COUNT 0, which is correctly not equal to 1.
674	func (r *renderer) renderTagExistsOne(field Field, pred PredicateExpr) (renderResult, error) {
675		arrayExpr := jsonArrayExpr(r.dialect, field)
676		elemCond, err := r.elementPredicateSQL(pred)
677		if err != nil {
678			return renderResult{}, err
679		}
680		switch r.dialect {
681		case DialectSQLite:
682			return renderResult{sql: fmt.Sprintf("(SELECT COUNT(*) FROM json_each(%s) WHERE %s) = 1", arrayExpr, elemCond)}, nil
683		case DialectMySQL:
684			return renderResult{sql: fmt.Sprintf("(SELECT COUNT(*) FROM JSON_TABLE(%s, '$[*]' COLUMNS (value VARCHAR(512) PATH '$')) AS elem WHERE %s) = 1", arrayExpr, elemCond)}, nil
685		case DialectPostgres:
686			return renderResult{sql: fmt.Sprintf("(SELECT COUNT(*) FROM jsonb_array_elements_text(%s) AS elem(value) WHERE %s) = 1", arrayExpr, elemCond)}, nil
687		default:
688			return renderResult{}, errors.Errorf("unsupported dialect %s", r.dialect)
689		}
690	}
691	
692	// elementPredicateSQL builds the per-element SQL condition for an all() predicate.
693	// The iterated element is exposed as the unqualified column `value` on all dialects
694	// (json_each.value / JSON_TABLE column / elem(value)).
695	func (r *renderer) elementPredicateSQL(pred PredicateExpr) (string, error) {
696		switch p := pred.(type) {
697		case *EqualsPredicate:
698			return fmt.Sprintf("value = %s", r.addArg(p.Value)), nil
699		case *StartsWithPredicate:
700			return r.foldedLike("value", likePattern(TextMatchPrefix, p.Prefix)), nil
701		case *EndsWithPredicate:
702			return r.foldedLike("value", likePattern(TextMatchSuffix, p.Suffix)), nil
703		case *ContainsPredicate:
704			return r.foldedLike("value", likePattern(TextMatchContains, p.Substring)), nil
705		default:
706			return "", errors.Errorf("unsupported predicate %T in all()", pred)
707		}
708	}
709	
710	// renderTagEquals generates SQL for tags.exists(t, t == "value").
711	func (r *renderer) renderTagEquals(field Field, value string, _ ComprehensionKind) (renderResult, error) {
712		arrayExpr := jsonArrayExpr(r.dialect, field)
713	
714		switch r.dialect {
715		case DialectSQLite, DialectMySQL:
716			exactMatch := r.buildJSONArrayLike(arrayExpr, fmt.Sprintf(`%%"%s"%%`, value))
717			return renderResult{sql: r.wrapWithNullCheck(arrayExpr, exactMatch)}, nil
718		case DialectPostgres:
719			exactMatch := fmt.Sprintf("%s @> jsonb_build_array(%s::json)", arrayExpr, r.addArg(fmt.Sprintf(`"%s"`, value)))
720			return renderResult{sql: r.wrapWithNullCheck(arrayExpr, exactMatch)}, nil
721		default:
722			return renderResult{}, errors.Errorf("unsupported dialect %s", r.dialect)
723		}
724	}
725	
726	// renderTagStartsWith generates SQL for tags.exists(t, t.startsWith("prefix")).
727	func (r *renderer) renderTagStartsWith(field Field, prefix string, _ ComprehensionKind) (renderResult, error) {
728		arrayExpr := jsonArrayExpr(r.dialect, field)
729	
730		switch r.dialect {
731		case DialectSQLite, DialectMySQL:
732			// Match exact tag or tags with this prefix (hierarchical support)
733			exactMatch := r.buildJSONArrayLike(arrayExpr, fmt.Sprintf(`%%"%s"%%`, prefix))
734			prefixMatch := r.buildJSONArrayLike(arrayExpr, fmt.Sprintf(`%%"%s%%`, prefix))
735			condition := fmt.Sprintf("(%s OR %s)", exactMatch, prefixMatch)
736			return renderResult{sql: r.wrapWithNullCheck(arrayExpr, condition)}, nil
737	
738		case DialectPostgres:
739			// Use PostgreSQL's powerful JSON operators
740			exactMatch := fmt.Sprintf("%s @> jsonb_build_array(%s::json)", arrayExpr, r.addArg(fmt.Sprintf(`"%s"`, prefix)))
741			prefixMatch := fmt.Sprintf("(%s)::text LIKE %s", arrayExpr, r.addArg(fmt.Sprintf(`%%"%s%%`, prefix)))
742			condition := fmt.Sprintf("(%s OR %s)", exactMatch, prefixMatch)
743			return renderResult{sql: r.wrapWithNullCheck(arrayExpr, condition)}, nil
744	
745		default:
746			return renderResult{}, errors.Errorf("unsupported dialect %s", r.dialect)
747		}
748	}
749	
750	// renderTagEndsWith generates SQL for tags.exists(t, t.endsWith("suffix")).
751	func (r *renderer) renderTagEndsWith(field Field, suffix string, _ ComprehensionKind) (renderResult, error) {
752		arrayExpr := jsonArrayExpr(r.dialect, field)
753		pattern := fmt.Sprintf(`%%%s"%%`, suffix)
754	
755		likeExpr := r.buildJSONArrayLike(arrayExpr, pattern)
756		return renderResult{sql: r.wrapWithNullCheck(arrayExpr, likeExpr)}, nil
757	}
758	
759	// renderTagContains generates SQL for tags.exists(t, t.contains("substring")).
760	func (r *renderer) renderTagContains(field Field, substring string, _ ComprehensionKind) (renderResult, error) {
761		arrayExpr := jsonArrayExpr(r.dialect, field)
762		pattern := fmt.Sprintf(`%%%s%%`, substring)
763	
764		likeExpr := r.buildJSONArrayLike(arrayExpr, pattern)
765		return renderResult{sql: r.wrapWithNullCheck(arrayExpr, likeExpr)}, nil
766	}
767	
768	// buildJSONArrayLike builds a LIKE expression for matching within a JSON array.
769	// Returns the LIKE clause without NULL/empty checks.
770	func (r *renderer) buildJSONArrayLike(arrayExpr, pattern string) string {
771		switch r.dialect {
772		case DialectSQLite, DialectMySQL:
773			return fmt.Sprintf("%s LIKE %s", arrayExpr, r.addArg(pattern))
774		case DialectPostgres:
775			return fmt.Sprintf("(%s)::text LIKE %s", arrayExpr, r.addArg(pattern))
776		default:
777			return ""
778		}
779	}
780	
781	// wrapWithNullCheck wraps a condition with NULL and empty array checks.
782	// This ensures we don't match against NULL or empty JSON arrays.
783	func (r *renderer) wrapWithNullCheck(arrayExpr, condition string) string {
784		var nullCheck string
785		switch r.dialect {
786		case DialectSQLite:
787			nullCheck = fmt.Sprintf("%s IS NOT NULL AND %s != '[]'", arrayExpr, arrayExpr)
788		case DialectMySQL:
789			nullCheck = fmt.Sprintf("%s IS NOT NULL AND JSON_LENGTH(%s) > 0", arrayExpr, arrayExpr)
790		case DialectPostgres:
791			nullCheck = fmt.Sprintf("%s IS NOT NULL AND jsonb_array_length(%s) > 0", arrayExpr, arrayExpr)
792		default:
793			return condition
794		}
795		return fmt.Sprintf("(%s AND %s)", condition, nullCheck)
796	}
797	
798	func (r *renderer) jsonBoolPredicate(field Field) (string, error) {
799		expr := jsonExtractExpr(r.dialect, field)
800		switch r.dialect {
801		case DialectSQLite:
802			return fmt.Sprintf("%s IS TRUE", expr), nil
803		case DialectMySQL:
804			return fmt.Sprintf("COALESCE(%s, CAST('false' AS JSON)) = CAST('true' AS JSON)", expr), nil
805		case DialectPostgres:
806			return fmt.Sprintf("(%s)::boolean IS TRUE", expr), nil
807		default:
808			return "", errors.Errorf("unsupported dialect %s", r.dialect)
809		}
810	}
811	
812	func combineAnd(left, right renderResult) renderResult {
813		if left.unsatisfiable || right.unsatisfiable {
814			return renderResult{sql: "1 = 0", unsatisfiable: true}
815		}
816		if left.trivial {
817			return right
818		}
819		if right.trivial {
820			return left
821		}
822		return renderResult{
823			sql: fmt.Sprintf("(%s AND %s)", left.sql, right.sql),
824		}
825	}
826	
827	func combineOr(left, right renderResult) renderResult {
828		if left.trivial || right.trivial {
829			return renderResult{trivial: true}
830		}
831		if left.unsatisfiable {
832			return right
833		}
834		if right.unsatisfiable {
835			return left
836		}
837		return renderResult{
838			sql: fmt.Sprintf("(%s OR %s)", left.sql, right.sql),
839		}
840	}
841	
842	func (r *renderer) addArg(value any) string {
843		r.placeholderCounter++
844		r.args = append(r.args, value)
845		if r.dialect == DialectPostgres {
846			return fmt.Sprintf("$%d", r.placeholderOffset+r.placeholderCounter)
847		}
848		return "?"
849	}
850	
851	func (r *renderer) addBoolArg(value bool) string {
852		var v any
853		switch r.dialect {
854		case DialectSQLite:
855			if value {
856				v = 1
857			} else {
858				v = 0
859			}
860		default:
861			v = value
862		}
863		return r.addArg(v)
864	}
865	
866	func expectLiteral(expr ValueExpr) (any, error) {
867		lit, ok := expr.(*LiteralValue)
868		if !ok {
869			return nil, errors.New("expression must be a literal")
870		}
871		return lit.Value, nil
872	}
873	
874	func expectBool(expr ValueExpr) (bool, error) {
875		lit, err := expectLiteral(expr)
876		if err != nil {
877			return false, err
878		}
879		value, ok := lit.(bool)
880		if !ok {
881			return false, errors.New("boolean literal required")
882		}
883		return value, nil
884	}
885	
886	func expectNumericLiteral(expr ValueExpr) (int64, error) {
887		lit, err := expectLiteral(expr)
888		if err != nil {
889			return 0, err
890		}
891		return toInt64(lit)
892	}
893	
894	func toInt64(value any) (int64, error) {
895		switch v := value.(type) {
896		case int:
897			return int64(v), nil
898		case int32:
899			return int64(v), nil
900		case int64:
901			return v, nil
902		case uint32:
903			return int64(v), nil
904		case uint64:
905			return int64(v), nil
906		case float32:
907			return int64(v), nil
908		case float64:
909			return int64(v), nil
910		default:
911			return 0, errors.Errorf("cannot convert %T to int64", value)
912		}
913	}
914	
915	func sqlOperator(op ComparisonOperator) string {
916		return string(op)
917	}
918	
919	func qualifyColumn(d DialectName, col Column) string {
920		switch d {
921		case DialectPostgres:
922			return fmt.Sprintf("%s.%s", col.Table, col.Name)
923		default:
924			return fmt.Sprintf("`%s`.`%s`", col.Table, col.Name)
925		}
926	}
927	
928	func jsonPath(field Field) string {
929		return "$." + strings.Join(field.JSONPath, ".")
930	}
931	
932	func jsonExtractExpr(d DialectName, field Field) string {
933		column := qualifyColumn(d, field.Column)
934		switch d {
935		case DialectSQLite, DialectMySQL:
936			return fmt.Sprintf("JSON_EXTRACT(%s, '%s')", column, jsonPath(field))
937		case DialectPostgres:
938			return buildPostgresJSONAccessor(column, field.JSONPath, true)
939		default:
940			return ""
941		}
942	}
943	
944	func jsonArrayExpr(d DialectName, field Field) string {
945		column := qualifyColumn(d, field.Column)
946		switch d {
947		case DialectSQLite, DialectMySQL:
948			return fmt.Sprintf("JSON_EXTRACT(%s, '%s')", column, jsonPath(field))
949		case DialectPostgres:
950			return buildPostgresJSONAccessor(column, field.JSONPath, false)
951		default:
952			return ""
953		}
954	}
955	
956	func jsonArrayLengthExpr(d DialectName, field Field) string {
957		arrayExpr := jsonArrayExpr(d, field)
958		switch d {
959		case DialectSQLite:
960			return fmt.Sprintf("JSON_ARRAY_LENGTH(COALESCE(%s, JSON_ARRAY()))", arrayExpr)
961		case DialectMySQL:
962			return fmt.Sprintf("JSON_LENGTH(COALESCE(%s, JSON_ARRAY()))", arrayExpr)
963		case DialectPostgres:
964			return fmt.Sprintf("jsonb_array_length(COALESCE(%s, '[]'::jsonb))", arrayExpr)
965		default:
966			return ""
967		}
968	}
969	
970	func buildPostgresJSONAccessor(base string, path []string, terminalText bool) string {
971		expr := base
972		for idx, part := range path {
973			if idx == len(path)-1 && terminalText {
974				expr = fmt.Sprintf("%s->>'%s'", expr, part)
975			} else {
976				expr = fmt.Sprintf("%s->'%s'", expr, part)
977			}
978		}
979		return expr
980	}
